PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?surgery_patient) AS ?patients_with_surgery)
       (COUNT(DISTINCT ?radiotherapy_patient) AS ?patients_with_radiotherapy)
       (COUNT(DISTINCT ?g) AS ?patients_with_either)
WHERE {
  {
    GRAPH ?g { ?surgery a sphn:OncologySurgery . }
    BIND (?g AS ?surgery_patient)
  }
  UNION
  {
    GRAPH ?g { ?radiotherapy a sphn:RadiotherapyProcedure . }
    BIND (?g AS ?radiotherapy_patient)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?year (COUNT(?diagnosis) AS ?billed_diagnoses) (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?diagnosis a sphn:BilledDiagnosis ;
               sphn:hasRecordDateTime ?recorded .
  }
  BIND (YEAR(?recorded) AS ?year)
}
GROUP BY ?year
ORDER BY ?year

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>

SELECT ?age_band_start (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?age a sphn:Age ;
         sphn:hasQuantity ?quantity .
    ?quantity sphn:hasValue ?age_value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:a .
  }
  BIND (FLOOR(?age_value / 10) * 10 AS ?age_band_start)
}
GROUP BY ?age_band_start
ORDER BY ?age_band_start

